      es: "Trincomalee es una gran ciudad portuaria en la costa este de Sri Lanka y cuenta con uno de los mejores puertos naturales de aguas profundas del mundo.",
      pt: "Trincomalee é uma grande cidade portuária na costa leste do Sri Lanka e possui um dos melhores portos naturais de águas profundas do mundo.",
      fr: "Trincomalee est une grande ville portuaire sur la côte est du Sri Lanka et dispose de l'un des meilleurs ports naturels en eau profonde au monde.",
