      es: ["El templo Koneswaram se encuentra pintorescamente en un acantilado sobre el océano.", "El puerto ha sido utilizado por muchos navegantes en la historia.", "Nilaveli y Uppuveli son algunas de las playas más hermosas de la ciudad.", "La región es un lugar popular para la observación de ballenas y delfines."],
      pt: ["O templo Koneswaram situa-se pitorescamente num penhasco sobre o oceano.", "O porto tem sido usado por muitos navegadores na história.", "Nilaveli e Uppuveli são algumas das praias mais bonitas da cidade.", "A região é um local popular para a observação de baleias e golfinhos."],
      fr: ["Le temple Koneswaram est situé de manière pittoresque sur une falaise au-dessus de l'océan.", "Le port a été utilisé par de nombreux navigateurs dans l'histoire.", "Nilaveli et Uppuveli sont parmi les plus belles plages de la ville.", "La région est un lieu populaire pour l'observation des baleines et des dauphins."],
