    id: "negombo-cities-v2", "sights": {"de": [{"name": "Negombo Dutch Fort", "text": "Eine historische Festung aus der niederländischen Kolonialzeit in Negombo.", "category": "historical", "coords": [79.831288, 7.208698]}, {"name": "Negombo Beach Park", "text": "An der Küste von Negombo verbindet dieser weitläufige Strandpark tropische Entspannung mit geselliger Unterhaltung. Palmen säumen den feinen Sand, während Besucher sowohl erholsame Stunden am Wasser als auch kurzweilige Freizeitaktivitäten genießen können. Die fröhliche Atmosphäre zieht Spaziergänger und Sonnenanbeter gleichermaßen an. Wer frische Meeresluft tanken möchte, sollte sich für einen Spaziergang am Morgen entscheiden.", "category": "recreational", "coords": [79.839947, 7.234976]}, {"name": "St. Sebastian Church", "text": "Eine markante Kirche im gotischen Stil, bekannt für ihre Architektur.", "category": "religious", "coords": [79.839194, 7.218358]}, {"name": "St. Mary's Church, Grand Street", "text": "Eine große historische katholische Kirche mit beeindruckenden Deckenmalereien.", "category": "religious", "coords": [79.837348, 7.210191]}], "hu": [{"name": "Negombo Dutch Fort", "text": "A holland gyarmati időszakban épült történelmi erőd Negombóban.", "category": "historical", "coords": [79.831288, 7.208698]}, {"name": "Negombo Beach Park", "text": "Negombo partjainál ez a kiterjedt strandpark a trópusi pihenést ötvözi a társasági szórakozással. Pálmafák szegélyezik a finom homokot, miközben a látogatók élvezhetik a nyugodt órákat a vízparton, valamint a szórakoztató szabadidős tevékenységeket. A vidám hangulat a sétálókat és a napozókat egyaránt vonzza. Ha friss tengeri levegőre vágyik, érdemes a kora reggeli sétát választani.", "category": "recreational", "coords": [79.839947, 7.234976]}, {"name": "St. Sebastian Church", "text": "Kiemelkedő gótikus stílusú templom, amely építészetéről ismert.", "category": "religious", "coords": [79.839194, 7.218358]}, {"name": "St. Mary's Church, Grand Street", "text": "Nagy múltú katolikus templom lenyűgöző mennyezeti festményekkel.", "category": "religious", "coords": [79.837348, 7.210191]}], "ro": [{"name": "Negombo Dutch Fort", "text": "O fortăreață istorică din perioada colonială olandeză în Negombo.", "category": "historical", "coords": [79.831288, 7.208698]}, {"name": "Negombo Beach Park", "text": "Pe coasta din Negombo, acest vast parc pe plajă combină relaxarea tropicală cu divertismentul social. Palmierii mărginesc nisipul fin, în timp ce vizitatorii se pot bucura atât de ore de odihnă la malul apei, cât și de activități distractive de agrement. Atmosfera veselă atrage atât iubitorii de plimbări, cât și pasionații de soare. Dacă doriți să respirați aer proaspăt de mare, ar trebui să optați pentru o plimbare matinală.", "category": "recreational", "coords": [79.839947, 7.234976]}, {"name": "St. Sebastian Church", "text": "O biserică proeminentă în stil gotic, cunoscută pentru arhitectura sa.", "category": "religious", "coords": [79.839194, 7.218358]}, {"name": "St. Mary's Church, Grand Street", "text": "O biserică catolică mare și istorică, cu picturi murale impresionante.", "category": "religious", "coords": [79.837348, 7.210191]}], "en": [{"name": "Negombo Dutch Fort", "text": "A historical fort built during the Dutch colonial period in Negombo.", "category": "historical", "coords": [79.831288, 7.208698]}, {"name": "Negombo Beach Park", "text": "Along the coast of Negombo, this expansive beach park beautifully combines tropical relaxation with social entertainment. Palm trees line the fine sand, while visitors can enjoy both restful hours by the water and engaging leisure activities. The cheerful atmosphere continuously attracts walkers and sunbathers alike. If you want to breathe in the fresh sea air, opt for a pleasant morning walk.", "category": "recreational", "coords": [79.839947, 7.234976]}, {"name": "St. Sebastian Church", "text": "A prominent Gothic-style church, known for its architecture.", "category": "religious", "coords": [79.839194, 7.218358]}, {"name": "St. Mary's Church, Grand Street", "text": "A large and historic Catholic church featuring impressive ceiling paintings.", "category": "religious", "coords": [79.837348, 7.210191]}]},
