    id: "matara-cities-v2", "sights": {"de": [{"name": "Polhena Beach", "text": "Dieser geschützte Strandabschnitt in Matara ist ein wahres Paradies für alle, die friedliche Gewässer schätzen. Dank des vorgelagerten Riffs wird die Brandung gebrochen, wodurch das Wasser außergewöhnlich ruhig und einladend bleibt. Familien und Erholungssuchende verbringen hier gerne unbeschwerte Tage mit Schwimmen und Sonnenbaden. Eine Schnorchelausrüstung einzupacken, ist aufgrund des sanften Wassers oft eine gute Idee.", "category": "recreational", "coords": [80.525886, 5.936188]}, {"name": "Old Dutch Market", "text": "Ein Gebäude aus der Kolonialzeit, das einst als zentraler Marktplatz diente.", "category": "historical", "coords": [80.535265, 5.947841]}, {"name": "Big Standing Buddha", "text": "Eine große Statue des stehenden Buddhas, ein Wahrzeichen in Matara.", "category": "historical", "coords": [80.571859, 5.941113]}, {"name": "The Shrine of Our Lady of Matara", "text": "Ein historisches katholisches Heiligtum mit einer verehrten Statue der Jungfrau Maria.", "category": "religious", "coords": [80.551908, 5.943294]}], "hu": [{"name": "Polhena Beach", "text": "Ez a védett partszakasz Matarában igazi paradicsom azok számára, akik értékelik a békés vizeket. A part menti zátonynak köszönhetően a hullámzás megtörik, így a víz rendkívül nyugodt és hívogató marad. A családok és a pihenni vágyók szívesen töltenek itt gondtalan napokat úszással és napozással. A szelíd víz miatt gyakran nagyszerű ötlet egy búvárfelszerelést is bepakolni a táskába.", "category": "recreational", "coords": [80.525886, 5.936188]}, {"name": "Old Dutch Market", "text": "Gyarmati korszakból származó épület, amely egykor központi piacként szolgált.", "category": "historical", "coords": [80.535265, 5.947841]}, {"name": "Big Standing Buddha", "text": "A hatalmas álló Buddha-szobor, Matara egyik nevezetessége.", "category": "historical", "coords": [80.571859, 5.941113]}, {"name": "The Shrine of Our Lady of Matara", "text": "Történelmi katolikus kegyhely Szűz Mária tisztelt szobrával.", "category": "religious", "coords": [80.551908, 5.943294]}], "ro": [{"name": "Polhena Beach", "text": "Această porțiune de plajă protejată din Matara este un adevărat paradis pentru toți cei care apreciază apele liniștite. Datorită recifului din larg, valurile sunt frânte, făcând apa excepțional de calmă și primitoare. Familiilor și celor în căutare de relaxare le place să petreacă zile fără griji înotând și făcând plajă aici. Împachetarea echipamentului de snorkeling este adesea o idee excelentă datorită apelor blânde.", "category": "recreational", "coords": [80.525886, 5.936188]}, {"name": "Old Dutch Market", "text": "O clădire din epoca colonială care a servit odată ca piață centrală.", "category": "historical", "coords": [80.535265, 5.947841]}, {"name": "Big Standing Buddha", "text": "O statuie mare a lui Buddha în picioare, un reper important în Matara.", "category": "historical", "coords": [80.571859, 5.941113]}, {"name": "The Shrine of Our Lady of Matara", "text": "Un sanctuar catolic istoric cu o statuie venerată a Fecioarei Maria.", "category": "religious", "coords": [80.551908, 5.943294]}], "en": [{"name": "Polhena Beach", "text": "This beautifully sheltered stretch of beach in Matara is a true paradise for anyone who appreciates peaceful waters. Thanks to the offshore reef, the surf is gracefully broken, keeping the water exceptionally calm and inviting. Families and those seeking pure relaxation love to spend carefree days swimming and sunbathing here. Packing snorkeling gear is often a great idea due to the very gentle waters.", "category": "recreational", "coords": [80.525886, 5.936188]}, {"name": "Old Dutch Market", "text": "A colonial-era building that once served as a central marketplace.", "category": "historical", "coords": [80.535265, 5.947841]}, {"name": "Big Standing Buddha", "text": "A large statue of the standing Buddha, a landmark in Matara.", "category": "historical", "coords": [80.571859, 5.941113]}, {"name": "The Shrine of Our Lady of Matara", "text": "A historic Catholic shrine housing a revered statue of the Virgin Mary.", "category": "religious", "coords": [80.551908, 5.943294]}]},
