    descriptionAdvanced: {
      de: "Kalutara ist eine bedeutende Küstenstadt in der Westprovinz Sri Lankas, etwa 40 Kilometer südlich von Colombo gelegen. Die Stadt liegt an der Mündung des Kalu Ganga, einem der wasserreichsten Flüsse des Landes, der eine zentrale Rolle für die lokale Wirtschaft spielt. Historisch war Kalutara ein strategisch wichtiger Posten für die portugiesischen, niederländischen und britischen Kolonialmächte, die hier Festungsanlagen errichteten. Das markanteste Wahrzeichen ist die Kalutara Bodhiya, eine massive hohle Stupa, die eine der heiligsten buddhistischen Stätten der Region beherbergt. Wirtschaftlich ist die Stadt für ihre Kautschukplantagen und die traditionelle Herstellung von handgeflochtenen Körben und Matten bekannt. Die Brücke über den Kalu Ganga verbindet den Norden mit dem Süden der Insel und ist ein wichtiger Verkehrsknotenpunkt. Heute kombiniert Kalutara industrielle Bedeutung mit touristischem Potenzial entlang seiner feinen Sandstrände.",
      hu: "Kalutara Srí Lanka nyugati partvidékének egyik jelentős városa, körülbelül 40 kilométerre délre Colombótól. A település a Kalu Ganga torkolatánál fekszik, amely az ország egyik legbővizűbb folyója és alapvető szerepet játszik a helyi gazdaságban. Történelmileg Kalutara stratégiai pont volt a portugál, holland és brit gyarmatosítók számára, akik erődítményeket emeltek a folyóparton. A város legfontosabb látnivalója a Kalutara Bodhiya, egy hatalmas, üreges sztúpa, amely a régió egyik legszentebb buddhista helyszíne. Gazdaságilag a város a gumiültetvényeiről és a hagyományos, kézzel font kosarairól és gyékényeiről ismert világszerte. A Kalu Ganga felett átívelő híd az ország egyik legfontosabb közlekedési csomópontja, összekötve a sziget északi és déli területeit. Napjainkban Kalutara sikeresen ötvözi az ipari tevékenységet a tengerparti turizmus kínálta lehetőségekkel.",
      ro: "Kalutara este un oraș de coastă important în Provincia de Vest din Sri Lanka, situat la aproximativ 40 de kilometri sud de Colombo. Orașul se află la gura de vărsare a râului Kalu Ganga, unul dintre cele mai mari cursuri de apă din țară, esențial pentru economia locală. Istoric, Kalutara a servit ca punct strategic pentru puterile coloniale portugheze, olandeze și britanice, care au construit fortificații aici. Cel mai proeminent punct de reper este Kalutara Bodhiya, o stupa masivă și goală la interior, care adăpostește unul dintre cele mai sfinte locuri budiste din regiune. Din punct de vedere economic, orașul este renumit pentru plantațiile de cauciuc și pentru fabricarea tradițională a coșurilor și rogojinilor împletite manual. Podul peste Kalu Ganga reprezintă un nod de transport vital, legând nordul de sudul insulei. Astăzi, Kalutara îmbină importanța industrială cu potențialul turistic de-a lungul plajelor sale cu nisip fin.",
      en: "Kalutara is a significant coastal city in Sri Lanka's Western Province, located about 40 kilometers south of Colombo. The city sits at the mouth of the Kalu Ganga, one of the country's major rivers, which plays a central role in the local economy. Historically, Kalutara was a strategic outpost for the Portuguese, Dutch, and British colonial powers, who established fortifications along the riverbanks. Its most prominent landmark is the Kalutara Bodhiya, a massive hollow stupa that houses one of the most sacred Buddhist sites in the region. Economically, the city is renowned for its rubber plantations and the traditional manufacture of hand-woven baskets and mats. The bridge over the Kalu Ganga is a vital transportation link, connecting the northern and southern parts of the island. Today, Kalutara combines industrial significance with tourism potential along its sandy beaches.",
      es: "Kalutara se encuentra a 42 kilómetros al sur de Colombo, en la desembocadura del Kalu Ganga en el Océano Índico, y cuenta con unos 38.000 habitantes. Fue parte del Reino de Kotte en el siglo XI, pasó a manos portuguesas en el siglo XVI y holandesas en 1655. Los holandeses construyeron un fuerte e introdujeron sistemáticamente el cultivo del coco. Durante el período colonial británico (1815-1948), la ciudad se conectó por ferrocarril en 1877. La estupa Kalutara Bodhiya, una dagoba de 50 metros de altura con un interior transitable diseñada por Geoffrey Bawa, se completó en 1980 y alberga un retoño del árbol Bodhi de Anuradhapura. Durante el tsunami del 26 de diciembre de 2004, alrededor de 270 personas murieron en la región. Hoy en día, Kalutara es famosa por su cultivo de mangostán y su cestería.",
      pt: "Kalutara está localizada a 42 quilômetros ao sul de Colombo, na foz do rio Kalu Ganga no Oceano Índico, e tem cerca de 38.000 habitantes. Foi parte do Reino de Kotte no século XI, tornou-se portuguesa no século XVI e holandesa em 1655. Os holandeses construíram um forte e introduziram sistematicamente o cultivo do coco. Durante o período colonial britânico (1815-1948), a cidade foi conectada por ferrovia em 1877. A estupa Kalutara Bodhiya, uma dagoba de 50 metros de altura com um interior acessível projetado por Geoffrey Bawa, foi concluída em 1980 e abriga uma muda da árvore Bodhi de Anuradhapura. Durante o tsunami de 26 de dezembro de 2004, cerca de 270 pessoas morreram na região. Hoje, Kalutara é famosa pelo cultivo de mangostão e pela cestaria.",
      fr: "Kalutara est située à 42 kilomètres au sud de Colombo, à l'embouchure du fleuve Kalu Ganga dans l'océan Indien, et compte environ 38 000 habitants. Elle faisait partie du royaume de Kotte au XIe siècle, est devenue portugaise au XVIe siècle et néerlandaise en 1655. Les Néerlandais y construisirent un fort et introduisirent systématiquement la culture de la noix de coco. Pendant la période coloniale britannique (1815-1948), la ville fut reliée par le chemin de fer en 1877. Le stoupa Kalutara Bodhiya, une dagoba de 50 mètres de haut avec une cavité intérieure accessible, conçu par Geoffrey Bawa, a été achevé en 1980 et abrite une pousse de l'arbre de la Bodhi d'Anuradhapura. Lors du tsunami du 26 décembre 2004, environ 270 personnes sont mortes dans la région. Aujourd'hui, Kalutara est célèbre pour sa culture du mangoustan et sa vannerie.",
    },
