        "Das Parakrama Samudra ist ein riesiges antikes Bewässerungsreservoir.",
        "Gal Vihara beherbergt beeindruckende Buddha-Statuen, die aus dem Felsen gehauen wurden.",
        "Die Stadt war im 12. Jahrhundert auf ihrem Höhepunkt."
