      hu: "Mullaitivu egy tengerparti város északkeleten, amely hosszú strandjairól, sűrű erdeiről és gazdag halászatáról ismert.",
      ro: "Mullaitivu este un oraș de coastă în nord-est, cunoscut pentru plajele sale lungi, pădurile dense și pescuitul bogat.",
      en: "Mullaitivu is a coastal town in the northeast, known for its long beaches, dense forests, and rich fishing grounds.",
      es: "Mullaitivu es una ciudad costera en el noreste, conocida por sus largas playas, densos bosques y rica industria pesquera.",
