      es: ["El famoso orfanato de elefantes de Pinnawala se encuentra a pocos kilómetros.", "La ciudad se encuentra en la ruta principal entre Colombo y Kandy.", "El caucho y el té son los productos agrícolas más importantes.", "La cercana roca 'Utuwankanda' fue el escondite del rebelde local Saradiel."],
      pt: ["O famoso orfanato de elefantes de Pinnawala fica a poucos quilômetros.", "A cidade fica na rota principal entre Colombo e Kandy.", "A borracha e o chá são os produtos agrícolas mais importantes.", "A rocha próxima 'Utuwankanda' foi o esconderijo do rebelde local Saradiel."],
      fr: ["Le célèbre orphelinat d'éléphants de Pinnawala se trouve à quelques kilomètres seulement.", "La ville se situe sur la route principale entre Colombo et Kandy.", "Le caoutchouc et le thé sont les produits agricoles les plus importants.", "Le rocher voisin 'Utuwankanda' fut la cachette du rebelle local Saradiel."],
