      pt: ["Moneragala é o segundo maior distrito do país em área.", "O Parque Nacional Yala, famoso pelos seus leopardos, estende-se até aqui.", "A cana-de-açúcar é cultivada em grande escala na região.", "É um paraíso para o ecoturismo e a observação da natureza."],
      fr: ["Moneragala est le deuxième plus grand district du pays par sa superficie.", "Le parc national de Yala, célèbre pour ses léopards, s'étend jusqu'ici.", "La canne à sucre est cultivée à grande échelle dans la région.", "C'est un paradis pour l'écotourisme et l'observation de la nature."],
